function ageFromDOB(d){if(!d)return null;const b=new Date(d+'T12:00:00'),n=new Date();let a=n.getFullYear()-b.getFullYear();if(n<new Date(n.getFullYear(),b.getMonth(),b.getDate()))a--;return a}
function calcTargets(p,calorieOverride=null){const weight=Number(p.current_weight||p.starting_weight_lb),height=Number(p.height_in),age=ageFromDOB(p.birth_date);if(!weight||!height||!age)return null;const kg=weight*.453592,cm=height*2.54,bmr=10*kg+6.25*cm-5*age+(p.sex==='female'?-161:p.sex==='male'?5:-78),mult={sedentary:1.2,light:1.375,moderate:1.55,very:1.725}[p.activity_level]||1.55,tdee=Math.round(bmr*mult);let calories=calorieOverride||Math.round((p.goal_type==='lose'?tdee-500:p.goal_type==='gain'?tdee+250:tdee)/50)*50;calories=Math.max(1200,Number(calories));let protein=Math.round((p.goal_type==='lose'?.8:.75)*weight);if(['vegan','vegetarian'].includes(p.diet_pattern))protein=Math.round(protein*1.05);let carbs,fat;if(p.diet_pattern==='keto'){carbs=25;fat=Math.max(25,Math.round((calories-protein*4-carbs*4)/9))}else if(p.diet_pattern==='low-carb'){carbs=Math.round(calories*.2/4);fat=Math.max(25,Math.round((calories-protein*4-carbs*4)/9))}else{fat=Math.max(25,Math.round(calories*.3/9));carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4))}const weekly=(calories-tdee)*7/3500;return{tdee,calories,protein,carbs,fat,weekly}}
async function latestWeight(p){const {data}=await db.from('weight_logs').select('weight_lb').order('logged_on',{ascending:false}).limit(1);return data?.[0]?Number(data[0].weight_lb):Number(p.starting_weight_lb||0)}
