function recipeMacros(r){const m={calories:0,protein:0,carbs:0,fat:0};(r.recipe_ingredients||[]).forEach(i=>{const f=i.foods,q=Number(i.quantity_g)/100;if(!f)return;m.calories+=Number(f.calories_100g)*q;m.protein+=Number(f.protein_100g)*q;m.carbs+=Number(f.carbs_100g)*q;m.fat+=Number(f.fat_100g)*q});return m}
function macroLine(m,p=1){return `${Math.round(m.calories*p)} kcal • ${Math.round(m.protein*p)}P • ${Math.round(m.carbs*p)}C • ${Math.round(m.fat*p)}F`}
function recipeAllowed(r,p){const d=p.diet_pattern||'none',tags=r.tags||[],names=(r.recipe_ingredients||[]).map(i=>i.foods?.name?.toLowerCase()||'').join(' '),ex=(p.hard_exclusions||[]).map(x=>x.toLowerCase());if(ex.some(x=>x&&names.includes(x)))return false;if(d==='keto'&&!tags.includes('keto'))return false;if(d==='low-carb'&&!tags.includes('low-carb'))return false;if(d==='paleo'&&!tags.includes('paleo'))return false;if(d==='vegetarian'&&!tags.includes('vegetarian'))return false;if(d==='vegan'&&!tags.includes('vegan'))return false;if(d==='pescatarian'&&!tags.includes('pescatarian')&&!tags.includes('vegetarian')&&!tags.includes('vegan'))return false;if(d==='mediterranean'&&!tags.includes('mediterranean'))return false;const rules=p.custom_diet_rules||{};if(d==='custom'){if(rules.meat==='none'&&/(chicken|beef|pork)/.test(names))return false;if(rules.fish==='none'&&/(salmon|fish|tuna)/.test(names))return false;if(rules.dairy==='none'&&/(cheese|yogurt|gouda|feta)/.test(names))return false;if(rules.eggs==='none'&&names.includes('eggs'))return false}return true}
